    // reduce x22,x12..x17,x19,x20 into [0, p)
    mov   x24, #-1
    movn  x23, #0xecc0, lsl #48      // p[8] = 0x133FFFFFFFFFFFFF
    subs  x22, x22, x24
    sbcs  x12, x12, x24
    sbcs  x13, x13, x24
    sbcs  x14, x14, x24
    sbcs  x15, x15, x24
    sbcs  x16, x16, x24
    sbcs  x17, x17, x24
    sbcs  x19, x19, x24
    sbcs  x20, x20, x23
    sbc   x24, xzr, xzr              // mask = -borrow
    and   x23, x23, x24
    adds  x22, x22, x24
    adcs  x12, x12, x24
    adcs  x13, x13, x24
    adcs  x14, x14, x24
    adcs  x15, x15, x24
    adcs  x16, x16, x24
    adcs  x17, x17, x24
    adcs  x19, x19, x24
    adc   x20, x20, x23
    stp   x22, x12, [x0]
    stp   x13, x14, [x0, #16]
    stp   x15, x16, [x0, #32]
    stp   x17, x19, [x0, #48]
    str   x20, [x0, #64]
    ldp   x23, x24, [sp, #32]
    ldp   x21, x22, [sp, #16]
    ldp   x19, x20, [sp], #48
    ret

