    sbcs  x21, x21, x23
    sbcs  x22, x22, x23
    sbcs  x12, x12, x23
    sbcs  x13, x13, x23
    sbcs  x14, x14, x23
    sbcs  x15, x15, x23
    sbcs  x16, x16, x23
    sbcs  x17, x17, x24
    sbc   x23, xzr, xzr              // mask = -borrow
    and   x24, x24, x23
    adds  x20, x20, x23
    adcs  x21, x21, x23
    adcs  x22, x22, x23
    adcs  x12, x12, x23
    adcs  x13, x13, x23
    adcs  x14, x14, x23
    adcs  x15, x15, x23
    adcs  x16, x16, x23
    adc   x17, x17, x24

    // c0 = P0 - P1 -> x3..x11
    ldp   x3, x4, [sp, #72]
    ldp   x5, x6, [sp, #88]
    ldp   x7, x8, [sp, #104]
    ldp   x9, x10, [sp, #120]
    ldr   x11, [sp, #136]
    movn  x24, #0xecc0, lsl #48      // p[8] = 0x133FFFFFFFFFFFFF
    subs  x3, x3, x20
    sbcs  x4, x4, x21
    sbcs  x5, x5, x22
    sbcs  x6, x6, x12
    sbcs  x7, x7, x13
    sbcs  x8, x8, x14
    sbcs  x9, x9, x15
    sbcs  x10, x10, x16
    sbcs  x11, x11, x17
    sbc   x23, xzr, xzr              // mask = -borrow
    and   x24, x24, x23
    adds  x3, x3, x23
    adcs  x4, x4, x23
    adcs  x5, x5, x23
    adcs  x6, x6, x23
    adcs  x7, x7, x23
    adcs  x8, x8, x23
    adcs  x9, x9, x23
    adcs  x10, x10, x23
    adc   x11, x11, x24
    stp   x3, x4, [x0]
    stp   x5, x6, [x0, #16]
    stp   x7, x8, [x0, #32]
    stp   x9, x10, [x0, #48]
    str   x11, [x0, #64]

    // c1 = (P2 - P1) - P0
    ldp   x3, x4, [sp]
    ldp   x5, x6, [sp, #16]
    ldp   x7, x8, [sp, #32]
    ldp   x9, x10, [sp, #48]
    ldr   x11, [sp, #64]
    movn  x24, #0xecc0, lsl #48      // p[8] = 0x133FFFFFFFFFFFFF
    subs  x3, x3, x20
    sbcs  x4, x4, x21
    sbcs  x5, x5, x22
    sbcs  x6, x6, x12
    sbcs  x7, x7, x13
    sbcs  x8, x8, x14
    sbcs  x9, x9, x15
    sbcs  x10, x10, x16
    sbcs  x11, x11, x17
    sbc   x23, xzr, xzr              // mask = -borrow
    and   x24, x24, x23
    adds  x3, x3, x23
    adcs  x4, x4, x23
    adcs  x5, x5, x23
    adcs  x6, x6, x23
    adcs  x7, x7, x23
    adcs  x8, x8, x23
    adcs  x9, x9, x23
    adcs  x10, x10, x23
    adc   x11, x11, x24
    ldp   x20, x21, [sp, #72]
    ldp   x22, x12, [sp, #88]
    ldp   x13, x14, [sp, #104]
    ldp   x15, x16, [sp, #120]
    ldr   x17, [sp, #136]
    movn  x24, #0xecc0, lsl #48      // p[8] = 0x133FFFFFFFFFFFFF
    subs  x3, x3, x20
    sbcs  x4, x4, x21
    sbcs  x5, x5, x22
    sbcs  x6, x6, x12
    sbcs  x7, x7, x13
    sbcs  x8, x8, x14
    sbcs  x9, x9, x15
    sbcs  x10, x10, x16
    sbcs  x11, x11, x17
    sbc   x23, xzr, xzr              // mask = -borrow
    and   x24, x24, x23
    adds  x3, x3, x23
    adcs  x4, x4, x23
    adcs  x5, x5, x23
    adcs  x6, x6, x23
    adcs  x7, x7, x23
    adcs  x8, x8, x23
    adcs  x9, x9, x23
    adcs  x10, x10, x23
    adc   x11, x11, x24
    stp   x3, x4, [x0, #72]
    stp   x5, x6, [x0, #88]
    stp   x7, x8, [x0, #104]
    stp   x9, x10, [x0, #120]
    str   x11, [x0, #136]
    ldp   x23, x24, [sp, #176]
    ldp   x21, x22, [sp, #160]
    ldp   x19, x20, [sp, #144]
    add   sp, sp, #192
    ret

//***********************************************************************
//  Squaring in GF(p^2)
//  Operation: c0 = (a0+a1) x (a0-a1) ; c1 = 2 a0 x a1
//    with a0+a1, a0-a1+p and 2*a0 kept unreduced (< 2p), so both
//    Montgomery products are < 2p before their final reduction.
//  Inputs: a = [a0, a1] stored in [x1]
//  Output: c = [c0, c1] stored in [x0]  (c may alias a)
//  Register allocation: multiplicand (d = a0-a1+p, then a1) = x3..x11;
//                       acc z0..z9 = x12..x17,x19..x22,
//                       scalar bi = x23, MULADD temp x24;
//                       scalars streamed from [sp].
//  Stack: [sp+0 .. 72) holds s = a0+a1;
//         [sp+72 .. 144) holds t = 2*a0.
//***********************************************************************
.global CDECL(fp2_sqr)
.p2align 6
CDECL(fp2_sqr):
    sub   sp, sp, #192               // 144 for s + t + 48 for callee saves
    stp   x19, x20, [sp, #144]
    stp   x21, x22, [sp, #160]
    stp   x23, x24, [sp, #176]

    // t = 2*a0 (unreduced) -> [sp+72] ; a0 stays in x3..x11
    ldp   x3, x4, [x1]
    ldp   x5, x6, [x1, #16]
    ldp   x7, x8, [x1, #32]
    ldp   x9, x10, [x1, #48]
    ldr   x11, [x1, #64]
    adds  x12, x3, x3
    adcs  x13, x4, x4
    adcs  x14, x5, x5
    adcs  x15, x6, x6
    adcs  x16, x7, x7
    adcs  x17, x8, x8
    adcs  x19, x9, x9
    adcs  x20, x10, x10
    adc   x21, x11, x11
    stp   x12, x13, [sp, #72]
    stp   x14, x15, [sp, #88]
    stp   x16, x17, [sp, #104]
    stp   x19, x20, [sp, #120]
    str   x21, [sp, #136]
    // s = a0 + a1 (unreduced) -> [sp]
    ldp   x12, x13, [x1, #72]
    ldp   x14, x15, [x1, #88]
    ldp   x16, x17, [x1, #104]
    ldp   x19, x20, [x1, #120]
    ldr   x21, [x1, #136]
    adds  x12, x12, x3
    adcs  x13, x13, x4
    adcs  x14, x14, x5
    adcs  x15, x15, x6
    adcs  x16, x16, x7
    adcs  x17, x17, x8
    adcs  x19, x19, x9
    adcs  x20, x20, x10
    adc   x21, x21, x11
    stp   x12, x13, [sp]
    stp   x14, x15, [sp, #16]
    stp   x16, x17, [sp, #32]
    stp   x19, x20, [sp, #48]
    str   x21, [sp, #64]
    // d = a0 - a1 + p (unreduced, in (0, 2p)) -> x3..x11
    ldp   x12, x13, [x1, #72]
    subs  x3, x3, x12
    sbcs  x4, x4, x13
    ldp   x12, x13, [x1, #88]
    sbcs  x5, x5, x12
    sbcs  x6, x6, x13
    ldp   x12, x13, [x1, #104]
    sbcs  x7, x7, x12
    sbcs  x8, x8, x13
    ldp   x12, x13, [x1, #120]
    sbcs  x9, x9, x12
    sbcs  x10, x10, x13
    ldr   x12, [x1, #136]
    sbcs  x11, x11, x12
    mov   x12, #-1
    movn  x13, #0xecc0, lsl #48      // p[8] = 0x133FFFFFFFFFFFFF
    adds  x3, x3, x12
    adcs  x4, x4, x12
    adcs  x5, x5, x12
    adcs  x6, x6, x12
    adcs  x7, x7, x12
    adcs  x8, x8, x12
    adcs  x9, x9, x12
    adcs  x10, x10, x12
    adc   x11, x11, x13

    // c0 = d x s -> [out] (a0's slot; a1 is still intact if c == a)
    // x12..x17,x19..x22 <- z = a x b0
    ldr   x23, [sp]
    MUL64x576  x12,x13,x14,x15,x16,x17,x19,x20,x21,x22, x3,x4,x5,x6,x7,x8,x9,x10,x11, x23, x24
    FPMUL576x576  sp, x3,x4,x5,x6,x7,x8,x9,x10,x11, x12,x13,x14,x15,x16,x17,x19,x20,x21,x22, x23, x24
    // reduce x22,x12..x17,x19,x20 into [0, p)
    mov   x23, #-1
    movn  x24, #0xecc0, lsl #48      // p[8] = 0x133FFFFFFFFFFFFF
    subs  x22, x22, x23
    sbcs  x12, x12, x23
    sbcs  x13, x13, x23
    sbcs  x14, x14, x23
    sbcs  x15, x15, x23
    sbcs  x16, x16, x23
    sbcs  x17, x17, x23
    sbcs  x19, x19, x23
    sbcs  x20, x20, x24
    sbc   x23, xzr, xzr              // mask = -borrow
    and   x24, x24, x23
    adds  x22, x22, x23
    adcs  x12, x12, x23
    adcs  x13, x13, x23
    adcs  x14, x14, x23
    adcs  x15, x15, x23
    adcs  x16, x16, x23
    adcs  x17, x17, x23
    adcs  x19, x19, x23
    adc   x20, x20, x24
    stp   x22, x12, [x0]
    stp   x13, x14, [x0, #16]
    stp   x15, x16, [x0, #32]
    stp   x17, x19, [x0, #48]
    str   x20, [x0, #64]

    // c1 = a1 x t -> [out+72]
    ldp   x3, x4, [x1, #72]
    ldp   x5, x6, [x1, #88]
    ldp   x7, x8, [x1, #104]
    ldp   x9, x10, [x1, #120]
    ldr   x11, [x1, #136]
    add   x1, sp, #72                // x1 is dead after the a1 load: reuse it as the t pointer
    // x22,x12..x17,x19..x21 <- z = a x b0
    ldr   x23, [x1]
    MUL64x576  x22,x12,x13,x14,x15,x16,x17,x19,x20,x21, x3,x4,x5,x6,x7,x8,x9,x10,x11, x23, x24
    FPMUL576x576  x1, x3,x4,x5,x6,x7,x8,x9,x10,x11, x22,x12,x13,x14,x15,x16,x17,x19,x20,x21, x23, x24
    // reduce x21,x22,x12..x17,x19 into [0, p)
    mov   x23, #-1
    movn  x24, #0xecc0, lsl #48      // p[8] = 0x133FFFFFFFFFFFFF
    subs  x21, x21, x23
    sbcs  x22, x22, x23
    sbcs  x12, x12, x23
    sbcs  x13, x13, x23
    sbcs  x14, x14, x23
    sbcs  x15, x15, x23
    sbcs  x16, x16, x23
    sbcs  x17, x17, x23
    sbcs  x19, x19, x24
    sbc   x23, xzr, xzr              // mask = -borrow
    and   x24, x24, x23
    adds  x21, x21, x23
    adcs  x22, x22, x23
    adcs  x12, x12, x23
    adcs  x13, x13, x23
    adcs  x14, x14, x23
    adcs  x15, x15, x23
    adcs  x16, x16, x23
    adcs  x17, x17, x23
    adc   x19, x19, x24
    stp   x21, x22, [x0, #72]
    stp   x12, x13, [x0, #88]
    stp   x14, x15, [x0, #104]
    stp   x16, x17, [x0, #120]
    str   x19, [x0, #136]
    ldp   x23, x24, [sp, #176]
    ldp   x21, x22, [sp, #160]
    ldp   x19, x20, [sp, #144]
    add   sp, sp, #192
    ret
